import mujoco
import numpy as np

m1 = mujoco.MjModel.from_xml_path('model_ref.xml')
m2 = mujoco.MjModel.from_xml_string(open('model_ref.xml').read())

# Check all opt attributes
for attr in dir(m1.opt):
    if not attr.startswith('_'):
        try:
            v1 = getattr(m1.opt, attr)
            v2 = getattr(m2.opt, attr)
            if isinstance(v1, (list, np.ndarray)):
                same = np.allclose(v1, v2)
            else:
                same = v1 == v2
            if not same:
                print(f'{attr}: DIFFERS m1={v1} m2={v2}')
        except:
            pass
print('All opt attributes checked')

# Check qpos0, qpos_spring
for attr in ['qpos0', 'qpos_spring']:
    try:
        v1 = getattr(m1, attr)
        v2 = getattr(m2, attr)
        if not np.allclose(v1, v2):
            print(f'{attr}: DIFFERS')
    except:
        pass
print('All qpos attributes checked')

# Check body attributes
for attr in ['body_mass', 'body_inertia', 'body_ipos', 'body_iquat', 'body_pos', 'body_quat', 'body_avel', 'body_cvel', 'body_cacc']:
    try:
        v1 = getattr(m1, attr)
        v2 = getattr(m2, attr)
        if not np.allclose(v1, v2):
            print(f'{attr}: DIFFERS')
    except:
        pass
print('All body attributes checked')
" 2>&1

